// The year-by-year story. Every line is a fact counted from the export, picked by
// the fixed rules below and written through a fixed template. No text is
// generated by a model, and nothing leaves the browser.
//
// How a year gets its lines:
//   1. Each rule that applies to the year adds a candidate with a weight.
//   2. Candidates are ranked by weight, one per topic.
//   3. The top two become the year's lines (a third joins if it is heavy enough),
//      and the heaviest one names the year.

import {num, pct} from '../format';
import {DAY_START_HOUR} from '../time';
import {CHAMPIONS} from './champions';
import type {Report, Story, StoryMark, StoryYear} from './types';

const DAY = 86400000;
const HOUR = 3600000;
/** 22:00 to 02:00. */
const NIGHT_HOURS = [22, 23, 0, 1];
/** Below this many login hours in a year, a share of them says nothing. */
const MIN_HOURS_FOR_SHARE = 30;
const THIRD_LINE_WEIGHT = 65;
const FILLER_WEIGHT = 20;

interface Candidate {
  topic: string;
  weight: number;
  /** Names the year when this is its heaviest candidate. */
  tag: string;
  text: string;
  mark?: StoryMark;
}

const monthDay = (t: number) => {
  const d = new Date(t);
  return `${d.getMonth() + 1}月${d.getDate()}日`;
};
/** Local noon of the calendar day an instant falls on. */
const noonOf = (t: number) => {
  const d = new Date(t);
  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 12).getTime();
};
const point = (t: number, label: string): StoryMark => ({kind: 'point', from: t, to: t, label});
/** The one entry holding the largest value, or null when the top is shared. */
function soleMax<T>(list: T[], value: (item: T) => number): T | null {
  if (list.length === 0) {
    return null;
  }
  const max = Math.max(...list.map(value));
  const tops = list.filter(item => value(item) === max);
  return tops.length === 1 ? tops[0] : null;
}

export function buildStory(r: Report): Story | null {
  const l = r.logins;
  if (!l || l.years.length === 0 || l.daily.counts.length === 0) {
    return null;
  }
  const y0 = l.years[0].year;
  const n = l.years.length;
  /** Local noon of the i-th recorded day. */
  const at = (i: number) => l.daily.start + i * DAY;
  const yearIndex = (t: number) => new Date(t).getFullYear() - y0;
  const candidates: Candidate[][] = l.years.map(() => []);
  const add = (t: number, c: Candidate) => candidates[yearIndex(t)]?.push(c);

  // ---- Walk the days once: running total, round-number days, runs of consecutive days.
  const cumulative = new Array<number>(n).fill(0);
  const runs: [number, number][] = [];
  let total = 0;
  let runStart = -1;
  l.daily.counts.forEach((hours, i) => {
    if (hours > 0) {
      total += 1;
      if (runStart < 0) {
        runStart = i;
      }
      if (total === 100 || total % 500 === 0) {
        add(at(i), {
          topic: 'milestone',
          weight: total % 1000 === 0 ? 90 : total % 500 === 0 ? 62 : 45,
          tag: `${num(total)}日目`,
          text: `${monthDay(at(i))}、ログイン${num(total)}日目。`,
          mark: point(at(i), `${num(total)}日目`),
        });
      }
    } else if (runStart >= 0) {
      runs.push([runStart, i - 1]);
      runStart = -1;
    }
    const k = yearIndex(at(i));
    if (k >= 0 && k < n) {
      cumulative[k] = total;
    }
  });
  if (runStart >= 0) {
    runs.push([runStart, l.daily.counts.length - 1]);
  }

  add(at(0), {
    topic: 'start',
    weight: 100,
    tag: 'はじまり',
    // A first login before 5 a.m. sits on the calendar under the night it belongs to.
    text: new Date(l.first).getHours() < DAY_START_HOUR ? `${monthDay(at(0))}の深夜、記録が始まる。` : `${monthDay(l.first)}、記録が始まる。`,
    mark: point(at(0), '記録開始'),
  });

  // ---- The longest run of consecutive days.
  const longest = runs.reduce((a, b) => (b[1] - b[0] > a[1] - a[0] ? b : a), runs[0]);
  const streak = longest ? longest[1] - longest[0] + 1 : 0;
  if (longest && streak >= 10) {
    add(at(longest[0]), {
      topic: 'streak',
      weight: 80,
      tag: `${num(streak)}日連続`,
      text: `${monthDay(at(longest[0]))}から${num(streak)}日連続でログイン。歴代最長。`,
      mark: {kind: 'streak', from: at(longest[0]), to: at(longest[1]), label: `${num(streak)}日連続`},
    });
  }

  // ---- Stretches of 30 days or more without a login.
  const gaps = runs
    .slice(1)
    .map((run, k) => ({from: runs[k][1] + 1, to: run[0] - 1}))
    .map(g => ({...g, days: g.to - g.from + 1}))
    .filter(g => g.days >= 30);
  const longestGap = Math.max(0, ...gaps.map(g => g.days));
  for (const g of gaps) {
    const isLongest = g.days === longestGap;
    add(at(g.from), {
      topic: 'gap',
      weight: isLongest ? 82 : 60 + Math.min(10, g.days / 20),
      tag: `${num(g.days)}日の空白`,
      text: `${monthDay(at(g.from))}から${num(g.days)}日間、ログインなし。${isLongest ? '歴代最長の空白。' : ''}`,
      mark: {kind: 'gap', from: at(g.from), to: at(g.to), label: `${num(g.days)}日の空白`},
    });
  }

  // ---- Login days: the most, the fewest, and sharp changes from the year before.
  if (n >= 3) {
    const most = soleMax(l.years, y => y.days);
    if (most) {
      const daysInYear = Math.round((new Date(most.year + 1, 0, 1, 12).getTime() - new Date(most.year, 0, 1, 12).getTime()) / DAY);
      candidates[most.year - y0].push({
        topic: 'days',
        weight: 92,
        tag: '全盛期',
        text: most.partial ? 'ログイン日数が歴代最多。' : `ログイン日数が歴代最多（1年の${pct(most.days / daysInYear)}）。`,
      });
    }
  }
  const whole = l.years.filter(y => !y.partial);
  if (whole.length >= 3) {
    const fewest = soleMax(whole, y => -y.days);
    if (fewest) {
      candidates[fewest.year - y0].push({
        topic: 'days',
        weight: 58,
        tag: '控えめな年',
        text: '1年まるごと記録がある年の中で、ログイン日数が最少。',
      });
    }
  }
  /** True when the year and the one before are both whole and within a quarter of each other. */
  const steady = l.years.map(() => false);
  for (let k = 1; k < n; k++) {
    const before = l.years[k - 1];
    const now = l.years[k];
    if (before.partial || now.partial || before.days === 0) {
      continue;
    }
    const diff = now.days - before.days;
    if (Math.abs(diff) / before.days >= 0.25) {
      candidates[k].push({
        topic: 'days',
        weight: 50,
        tag: diff > 0 ? 'ペースアップ' : 'ペースダウン',
        text: `ログイン日数が前の年より${num(Math.abs(diff))}日${diff > 0 ? '増えた' : '減った'}。`,
      });
    } else {
      steady[k] = true;
    }
  }

  // ---- Late nights: the year with the largest share, and sharp shifts.
  const night = l.hoursByYear.map(hours => {
    const sum = hours.reduce((a, v) => a + v, 0);
    return sum >= MIN_HOURS_FOR_SHARE ? NIGHT_HOURS.reduce((a, h) => a + hours[h], 0) / sum : null;
  });
  const nightKnown = night.map((share, k) => ({share, k})).filter((x): x is {share: number; k: number} => x.share != null);
  if (nightKnown.length >= 3) {
    const peak = soleMax(nightKnown, x => x.share);
    const sorted = nightKnown.map(x => x.share).sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)];
    if (peak && peak.share >= 0.5 && peak.share - median >= 0.1) {
      candidates[peak.k].push({
        topic: 'night',
        weight: 70,
        tag: '夜型のピーク',
        text: '深夜（22時〜翌2時）の割合が歴代最高。',
      });
    }
  }
  for (let k = 1; k < n; k++) {
    const before = night[k - 1];
    const now = night[k];
    if (before == null || now == null || Math.abs(now - before) < 0.15) {
      continue;
    }
    const up = now > before;
    candidates[k].push({
      topic: 'night',
      weight: 66,
      tag: up ? '夜型へ' : '夜ふかしが減る',
      text: `深夜（22時〜翌2時）の割合が、前の年の${pct(before)}から${up ? '上がった' : '下がった'}。`,
    });
  }

  // ---- Money: the first charge (and what was bought right after), and the top year.
  const spend: (number | null)[] = l.years.map(() => (r.spend ? 0 : null));
  if (r.spend) {
    for (const y of r.spend.years) {
      if (y.year - y0 >= 0 && y.year - y0 < n) {
        spend[y.year - y0] = y.amount;
      }
    }
    const first = r.spend.charges[0];
    if (first) {
      let text = `${monthDay(first.t)}に、初めてRPをチャージ。`;
      const next = r.store?.skinLog.find(s => s.t >= first.t && s.rp < 0);
      const who = next ? CHAMPIONS[next.id]?.[0] : undefined;
      if (next && who && next.t - first.t <= HOUR) {
        const minutes = Math.round((next.t - first.t) / 60000);
        text += minutes < 1 ? `その直後に、${who}のスキンを購入。` : `その${minutes}分後に、${who}のスキンを購入。`;
      }
      add(first.t, {topic: 'first-charge', weight: 88, tag: '初課金', text, mark: point(noonOf(first.t), '初課金')});
    }
    const paid = r.spend.years.filter(y => y.amount > 0);
    const top = paid.length >= 2 ? soleMax(paid, y => y.amount) : null;
    if (top) {
      candidates[top.year - y0]?.push({topic: 'spend', weight: 75, tag: '課金ピーク', text: '課金額が歴代最多。'});
    }
  }

  // ---- Skins: how many each year, for which champions, and the top year.
  const skins = l.years.map(() => (r.store ? {total: 0, per: new Map<number, number>()} : null));
  for (const s of r.store?.skinLog ?? []) {
    const row = skins[yearIndex(s.t)];
    if (row) {
      row.total += 1;
      row.per.set(s.id, (row.per.get(s.id) ?? 0) + 1);
    }
  }
  const withSkins = skins.map((row, k) => ({total: row?.total ?? 0, k})).filter(x => x.total > 0);
  const skinPeak = withSkins.length >= 2 ? soleMax(withSkins, x => x.total) : null;
  if (skinPeak && skinPeak.total >= 5) {
    candidates[skinPeak.k].push({
      topic: 'skins',
      weight: 60,
      tag: 'スキン収集のピーク',
      text: 'スキン・クロマの入手数が歴代最多。',
    });
  }

  // ---- Skins: a year in which one champion took a large share of them.
  skins.forEach((row, k) => {
    if (!row || row.total < 8) {
      return;
    }
    const top = soleMax([...row.per.entries()], ([, count]) => count);
    const name = top ? CHAMPIONS[top[0]]?.[0] : undefined;
    if (!top || !name || top[1] < 5 || top[1] / row.total < 0.25) {
      return;
    }
    const share = top[1] / row.total;
    const part = share >= 1 / 2 ? '半分以上' : share >= 1 / 3 ? '3件に1件以上' : '4件に1件以上';
    candidates[k].push({topic: 'champion', weight: 57, tag: `${name}推し`, text: `入手したスキン・クロマの${part}が${name}。`});
  });

  // ---- Riot games picked up along the way: the first login to each, unless it sits at the very start of the record.
  const picked = new Map<number, typeof l.games>();
  for (const game of l.games) {
    const k = yearIndex(game.first);
    if (game.days >= 3 && game.first - l.first >= 30 * DAY && candidates[k]) {
      picked.set(k, [...(picked.get(k) ?? []), game]);
    }
  }
  for (const [k, games] of picked) {
    games.sort((a, b) => a.first - b.first);
    const [game] = games;
    candidates[k].push(
      games.length === 1
        ? {
            topic: 'game',
            weight: 55,
            tag: `${game.label}を開始`,
            text: `${new Date(game.first).getMonth() + 1}月、${game.label}に初めてログイン。`,
            mark: point(noonOf(game.first), game.label),
          }
        : {
            // Several in one year: one line names them all, and the calendar stays uncluttered.
            topic: 'game',
            weight: Math.min(86, 55 + 10 * (games.length - 1)),
            tag: `新しいゲーム${games.length}本`,
            text: `${games.map(g => g.label).join('、')}に初めてログイン。`,
          },
    );
  }

  // ---- A year without a single login.
  l.years.forEach((y, k) => {
    if (y.days === 0) {
      candidates[k].push({topic: 'none', weight: 95, tag: 'お休み', text: 'ログインした日の記録なし。'});
    }
  });

  // ---- Always available: the busiest month of the year.
  l.yearMonth.forEach((months, k) => {
    const max = Math.max(0, ...months.map(v => v ?? 0));
    const tops = months.map((v, m) => ({v, m})).filter(x => x.v === max);
    if (max === 0 || tops.length > 2) {
      return;
    }
    const names = tops.map(x => `${x.m + 1}月`);
    candidates[k].push({
      topic: 'month',
      weight: FILLER_WEIGHT,
      tag: `${names[0]}がピーク`,
      text:
        tops.length === 1
          ? `${names[0]}に${num(max)}日ログイン。この年でいちばん多い月。`
          : `${names.join('と')}に各${num(max)}日ログイン。この年でいちばん多い月。`,
    });
  });

  // ---- Pick the lines.
  const years: StoryYear[] = l.years.map((y, k) => {
    const byTopic = new Map<string, Candidate>();
    for (const c of [...candidates[k]].sort((a, b) => b.weight - a.weight)) {
      if (!byTopic.has(c.topic)) {
        byTopic.set(c.topic, c);
      }
    }
    const ranked = [...byTopic.values()];
    const chosen = ranked.slice(0, 2);
    if (ranked[2] && ranked[2].weight >= THIRD_LINE_WEIGHT) {
      chosen.push(ranked[2]);
    }
    const isLast = k === n - 1;
    const lines = chosen.map(c => c.text);
    if (isLast) {
      // A last login before 5 a.m. sits on the calendar under the night it belongs to.
      const end = l.daily.start + (l.daily.counts.length - 1) * DAY;
      lines.push(new Date(l.last).getHours() < DAY_START_HOUR ? `記録は${monthDay(end)}の深夜まで。` : `記録は${monthDay(l.last)}まで。`);
    }
    const top = chosen[0];
    const tag = top && top.weight > FILLER_WEIGHT ? top.tag : isLast ? '現在' : steady[k] ? '安定期' : (top?.tag ?? `${y.year}年`);
    // Marks for the lines shown, plus any streak or gap of the year: those are visible on the calendar anyway.
    const marks = ranked
      .filter(c => c.mark && (chosen.includes(c) || c.mark.kind !== 'point'))
      .map(c => c.mark as StoryMark);
    const row = skins[k];
    return {
      year: y.year,
      partial: y.partial,
      days: y.days,
      cumulative: cumulative[k],
      nightShare: night[k],
      hours: l.hoursByYear[k],
      spend: spend[k],
      skins: row
        ? {
            total: row.total,
            champions: row.per.size,
            top: [...row.per.entries()]
              .map(([id, count]) => ({id, name: CHAMPIONS[id]?.[0] ?? `ID ${id}`, count}))
              .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name, 'ja'))
              .slice(0, 6),
          }
        : null,
      tag,
      lines,
      marks,
    };
  });

  // A streak or gap that runs past New Year is marked in every year it touches.
  const spans = years.flatMap(y => y.marks.filter(m => m.kind !== 'point'));
  for (const y of years) {
    const from = new Date(y.year, 0, 1).getTime();
    const to = new Date(y.year + 1, 0, 1).getTime();
    for (const m of spans) {
      if (!y.marks.includes(m) && m.to >= from && m.from < to) {
        y.marks.push(m);
      }
    }
  }

  return {years, currency: r.spend?.currency ?? null};
}
